#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        int N;
        cin>>N;
        int n=3*N;
        vector<long long>ans(n);
        for(int i=0;i<n;i++){
            cin>>ans[i];
        }
        sort(ans.rbegin(),ans.rend());
        vector<long long>a(n+1,0);
        for(int i=0;i<n;i++){
            a[i+1]=a[i]+ans[i];
            
        }
        long long c =0;
        for(int i=0;i<=N;i++){
            int l=0,r=N-i;
            while(l<r){
                int mid=(l+r)/2;
                int q=i+2*mid;
                int p=3*N-2*i-mid;
                long long diff=ans[q]+ans[q+1]-3LL*ans[p-1];
                if(diff>=0){
                    l=mid+1;
                }
                else{
                    r=mid;
                }
            }
            int j=l;
            int temp=N-i-j;
            int p=i;
            int q=p+2*j;
            int u=q+3*temp;
            long long st=6LL*a[p]+4LL*(a[q]-a[p])+3LL*(a[u]-a[q]);
            c=max(c,st);
        }
        cout<<c<<"\n";
        
    }
   
}
